mutations.find:
let sessions = 0;
for (let attempt = 0; attempt < m; attempt++) {
  sessions++;
  if (oracle.runTamperedSession(delta)) {
    return { index, delta, sessions, accepted: true, bit: 0 };
  }
}
return { index, delta, sessions, accepted: false, bit: 1 };

mutations.replace:
let sessions = 0;
let accepts = 0;
for (let attempt = 0; attempt < m; attempt++) {
  sessions++;
  if (oracle.runTamperedSession(delta)) accepts++;
}
const decided: Bit = 2 * accepts > m ? 0 : 1;
return { index, delta, sessions, accepted: accepts > 0, bit: decided };
